import re

from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output, log_result,
)
from taf.rfrl.procedures.resources.python.parser.exceptions import (
    SOAPValidationError,
)


@log_input_and_output
def is_message_in_file(dist_name, class_name, content, soap_path):
    r"""
    Searches SOAP file for message with specified data.

    :param dist_name: distName of managedObject from SOAP message to search for;
                      either raw string or regex can be used;
                      e.g.: 'arrayVswrSupervision1' or 'arrayVswrSupervision\d{1}'
    :type dist_name: str
    :param class_name: class of managedObject from SOAP message to search for;
                       either raw string or regex can be used;
                       e.g.: 'ArrayVswrSupervision' or '.+Supervision'
    :type class_name: str
    :param content: content of SOAP message to search for as a list of strings;
                    each string represents one expected line in SOAP message;
                    either raw strings or regex can be used;
                    e.g.: ['<parameterName>speed</parameterName>', '<newValue>19</newValue>']
                          or
                          ['<parameterName>[a-z,A-Z]+</parameterName>', '<newValue>\d+</newValue>']
    :type content: list of str
    :param soap_path: absolute path with filename and extension to SOAP file, e.g. /tmp/rf_soap.xml
    :type soap_path: str
    :return: True if message with specified data is found in SOAP file, False otherwise
    :rtype: bool
    """
    expected_msg = [f'<managedObject distName="{dist_name}" class="{class_name}">'] + content
    soap_messages = _get_soap_data(soap_path)

    missed_lines = []
    for line in expected_msg:
        if not any(re.search(line, soap_msg) for soap_msg in soap_messages):
            missed_lines.append(line)

    if not missed_lines:
        log_result(f'Message {expected_msg} found in SOAP file')
        return True

    log_result(f'Message {expected_msg} not found in SOAP file. Missed lines: {missed_lines}')
    return False


@log_input_and_output
def check_if_feature_instance_is_available_in_features(feature_distname, soap_path):
    """
    Checks if feature instance (feature_distname) exist in SOAP file (soap_path). Feature instance should be generated
    in SOAP after BTS site reset.

    :param feature_distname: instance feature distname to check, e.g.: 'cpuCoreDump'
    :type feature_distname: str
    :param soap_path: absolute path with filename and extension to soap file, e.g. /tmp/rf_soap.xml
    :type soap_path: str
    :return: feature instance found in SOAP file
    :rtype: str

    :raises SOAPValidationError: if particular feature instance is not found in SOAP file
    """
    soap_data = _get_soap_data(soap_path)

    for soap in soap_data:
        if '<managedObject distName="features" class="Features">' in soap:
            if re.search(rf'<managedObject distName="features" class="Features">.*<instance>{feature_distname}'
                         rf'</instance>.*</managedObject>', soap):
                log_result(f'Message found in SOAP file: {soap}')
                return soap

    raise SOAPValidationError(f"Feature instance with distname: {feature_distname} is not found in SOAP file.")


@log_input_and_output
def check_feature_enabling(feature_distname, soap_path):
    """
    Checks if feature (feature_distname) enabling is visible in SOAP file (soap_path). Feature enabling should be
    generated in SOAP during feature activation in SCF configuration.

    :param feature_distname: instance feature distname to check, e.g.: 'cpuCoreDump'
    :type feature_distname: str
    :param soap_path: absolute path with filename and extension to soap file, e.g. /tmp/rf_soap.xml
    :type soap_path: str
    :return: feature enabling message found in SOAP file
    :rtype: str

    :raises SOAPValidationError: if enabling of particular feature is not found in SOAP file
    """
    soap_data = _get_soap_data(soap_path)

    for soap in soap_data:
        if all([f'<managedObject distName="{feature_distname}" class="Feature">' in soap,
                '<parameterName>enabled</parameterName>' in soap,
                '<parameterName>subscribe</parameterName>' not in soap,
                '<newValue>TRUE</newValue>' in soap,
                '<prevValue>FALSE</prevValue>' in soap]):
            log_result(f'Message found in SOAP file: {soap}')
            return soap

    raise SOAPValidationError(f"Feature enabling with distname: {feature_distname} is not found in SOAP file.")


@log_input_and_output
def check_if_rmod_alarm_is_present_in_soap_logs(local_rmod_id, fault_id, soap_path):
    """
    Checks if RMOD's alarm (fault_id) is visible in SOAP file (soap_path).

    :param local_rmod_id: local rmod id given from RMOD_L object, e.g.: "1"
    :type local_rmod_id: str or int
    :param fault_id: alarm id to check, e.g.: 2933
    :type fault_id: str or int
    :param soap_path: absolute path with filename and extension to soap file, e.g. /tmp/rf_soap.xml
    :type soap_path: str
    :return: RMOD's alarm message found in SOAP file
    :rtype: str

    :raises SOAPValidationError: if RMOD's alarm is not found in SOAP file
    """
    soap_data = _get_soap_data(soap_path)

    for soap in soap_data:
        if all([f'RMOD_L_{local_rmod_id}' in soap,
                '<faultSource>module</faultSource>' in soap,
                f'<faultId>{fault_id}</faultId>' in soap,
                '<faultState>active</faultState>' in soap]):
            log_result(f'Message found in SOAP file: {soap}')
            return soap

    raise SOAPValidationError(f"RMOD alarm {fault_id} send to DU is not found in SOAP file.")


def _get_soap_data(soap_path):
    """
    Gets soap data.

    :param soap_path: absolute path with filename and extension to pcap file, e.g. /tmp/gnb_logs.pcap
    :type soap_path: str
    :return list of soap data
    :rtype: list
    """
    with open(soap_path, "r") as soap:
        output = soap.read()
        soap_data = re.split('<UTC-Timestamp>', output)
        return ['<UTC-Timestamp>' + soap for soap in soap_data if soap]
